mapper.insert:
INSERT INTO tb_course_instructors (
    id, course_id, user_id, instructor_role, assigned_at, created_at
) VALUES (
    #{id}, #{courseId}, #{userId}, #{role}, #{assignedAt}, #{createdAt}
)

mapper.select:
SELECT id, course_id, user_id, instructor_role, assigned_at, created_at
  FROM tb_course_instructors
 WHERE course_id = #{courseId}
   AND user_id = #{userId}

SELECT EXISTS (
    SELECT 1
      FROM tb_course_instructors
     WHERE course_id = #{courseId}
       AND user_id = #{userId}
)

SELECT EXISTS (
    SELECT 1
      FROM tb_course_instructors
     WHERE course_id = #{courseId}
       AND user_id = #{userId}
       AND instructor_role = #{role}
)

SELECT EXISTS (
    SELECT 1
      FROM tb_course_instructors ci
      JOIN tb_courses c ON c.id = ci.course_id
     WHERE ci.user_id = #{userId}
       AND c.institution_id = #{institutionId}
)

mapper.update:
UPDATE tb_course_instructors
   SET instructor_role = #{instructor.role},
       assigned_at = #{instructor.assignedAt}
 WHERE course_id = #{instructor.courseId}
   AND user_id = #{instructor.userId}
   AND instructor_role = #{expectedRole}

mapper.delete:
DELETE FROM tb_course_instructors
 WHERE course_id = #{courseId}
   AND user_id = #{userId}
